function ovr(a,m,d,g){return Math.round(.32*a+.30*m+.28*d+.10*g)}
function cl2(v){return Math.max(25,Math.min(99,Math.round(v)))}
function seedR(s){var h=1779033703^s.length;for(var i=0;i<s.length;i++){h=Math.imul(h^s.charCodeAt(i),3432918353);h=h<<13|h>>>19}
  return function(){h=Math.imul(h^h>>>16,2246822507);h=Math.imul(h^h>>>13,3266489909);h^=h>>>16;return(h>>>0)/4294967296}}
function mkStats(n,r){
  var s=STY[n],d;
  if(s)d=s.slice();
  else{var R=seedR(n),sg=r>=75?2.5:r>=60?3.5:4.5;d=[(R()*2-1)*sg*1.3,(R()*2-1)*sg*1.1,(R()*2-1)*sg*1.3,(R()*2-1)*sg*.9]}
  var w=[.32,.30,.28,.10],avg=0;d.forEach(function(x,i){avg+=w[i]*x});
  var v=d.map(function(x){return cl2(r+x-avg)});
  var k=0;while(ovr(v[0],v[1],v[2],v[3])!==r&&k++<12){var diff=r-ovr(v[0],v[1],v[2],v[3]);v[k%3]=cl2(v[k%3]+(diff>0?1:-1))}
  return v;
}
TEAMS.forEach(function(t){var v=mkStats(t.n,t.r);t.a=v[0];t.m=v[1];t.d=v[2];t.g=v[3]});

