var NATS=[];Object.keys(NATS_RAW).forEach(function(c){NATS_RAW[c].split(',').forEach(function(s){var i=s.lastIndexOf(' ');NATS.push({n:s.slice(0,i),r:+s.slice(i+1),c:c,k:'nat'});CR[s.slice(0,i)]=[hue(s.slice(0,i)),'band','#fff']})});
var CLUBS=TEAMS.map(function(t){return{n:t.n,r:t.r,c:t.c,l:t.l,k:'club',a:t.a,m:t.m,d:t.d,g:t.g}});
