function myHist(){let w=0,d=0,l=0,gf=0,gc=0,rows='';T.stages.forEach(st=>{(st.R||[]).forEach((r,ri)=>r.forEach(m=>{if(m.hg==null||(m.h!=T.me&&m.a!=T.me))return;const h=m.h==T.me,a=h?m.hg:m.ag,b=h?m.ag:m.hg,o=T.teams[h?m.a:m.h];gf+=a;gc+=b;let r2=a>b?'G':a<b?'P':'E';if(a==b&&m.pen){const pm=h?m.pen[0]:m.pen[1],po=h?m.pen[1]:m.pen[0];r2=pm>po?'G':'P'}r2=='G'?w++:r2=='P'?l++:d++;rows+=`<div class=fx><span class=t>${st.k=='ko'?st.rn[ri]:'J'+(ri+1)} · ${o.n} ${crest(o.n,18)}</span><b style="color:${r2=='G'?'#4c4':r2=='P'?'#e55':'#ccc'}">${a} - ${b}${m.pen?' (p)':''}</b></div>`}))});return `<div class=card style="text-align:center"><b>${w} G · ${d} E · ${l} P</b><br><span class=m>Goles ${gf} a favor · ${gc} en contra</span></div><h2>Mis partidos</h2><div class=card>${rows||'<p class=m>Todavía no jugaste.</p>'}</div>`}
function dl(name,obj){try{const b=new Blob([JSON.stringify(obj)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000)}catch(e){alert('No se pudo exportar')}}
const ago=ts=>{const m=Math.round((Date.now()-ts)/60000);return m<1?'recién':m<60?m+' min':m<1440?Math.round(m/60)+' h':Math.round(m/1440)+' d'};
