const th=n=>cupTheme(n||'');
function applyTheme(n){const t=th(n);document.documentElement.style.setProperty('--a',t.a);document.documentElement.style.setProperty('--d',t.d);document.documentElement.style.setProperty('--b1',t.b1)}
function seg(k,opts,cur){if(cur!=null&&cur!==''&&/^(dur|lim|diff|fmt)$/.test(k)&&!opts.some(o=>String(o[0])===String(cur)))opts=opts.concat([[cur,k=='dur'?cur+' min':String(cur)]]);return `<div class=seg>${opts.map(o=>`<button data-a=set data-v="${k}:${o[0]}" class="${cur==o[0]?'on':''}">${o[1]}</button>`).join('')}</div>`}
function fx(m,mark){const A=T.teams[m.h],B=T.teams[m.a],me=m.h==T.me||m.a==T.me;return `<div class=fx ${m.hg!=null&&m.u?`data-a=md data-v=${m.u}`:''} style="${me?'color:var(--a)':''}${m.hg!=null&&m.u?';cursor:pointer':''}"><span class=t>${A.n} ${crest(A.n,20)}</span><b>${m.hg==null?'vs':m.hg+' - '+m.ag}${m.pen?`<small class=m><br>(${m.pen[0]}-${m.pen[1]} p)</small>`:''}</b><span class=t>${crest(B.n,20)} ${B.n}</span></div>`}
function tbl(st,ids){const r=rows(st,ids);return `<table><tr><th></th><th></th><th>PJ</th><th>DG</th><th>Pts</th></tr>${r.map((x,i)=>`<tr class="${x.i==T.me?'me':''}"><td>${i+1}</td><td>${crest(T.teams[x.i].n,16)} ${T.teams[x.i].n}</td><td>${x.pj}</td><td>${x.gf-x.gc}</td><td>${x.pts}</td></tr>`).join('')}</table>`}
