function rpClose(){if(!RP)return;const sn=RP.snap;P.forEach((p,i)=>Object.assign(p,sn.P[i]));Object.assign(B,sn.B);RP=null;$('rp').hidden=true;if(fin)$('end').hidden=false;else $('pm').hidden=false;pDr=false}
$('rpx').onclick=rpClose;$('rpp').onclick=()=>{if(!RP)return;if(!RP.play&&RP.i>=RP.c.n-1)RP.i=0;RP.play=!RP.play;rpUi()};$('rpc').onclick=()=>{RP.i=0;RP.play=false;rpUi()};
