function roster(tn){const q=SQP[tn];return q?['G','D','M','F'].reduce((a,g)=>a.concat(q[g].map(nm=>({nm,g}))),[]):null}
function lineup(tn,n,pick){const q=SQP[tn],R=['F','M','G'].slice(0,n);if(!q)return{nm:R.map((r,i)=>ROL[i]),slot:0};const used=new Set(),out=R.map(()=>null);let slot=0;const L=pick>=0&&roster(tn)[pick];
if(L){slot=L.g=='F'?0:L.g=='G'?Math.min(n-1,2):Math.min(n-1,1);out[slot]=L.nm;used.add(L.nm)}
R.forEach((r,i)=>{if(out[i])return;const pool=(q[r]||[]).concat(r=='M'?q.D:[]).filter(x=>!used.has(x));out[i]=pool[0]||ROL[i];used.add(out[i])});return{nm:out,slot}}
function squadOf(tn,n){return lineup(tn,n,-1).nm}
function updSq(){const sel=$('qp');if(!sel||!window.__all||!$('qa')||!$('qb'))return;const a=window.__all[+$('qa').value],b=window.__all[+$('qb').value];if(!a||!b)return;const n=C.mode&&C.mode!='prac'?1:+C.fmt||3,r=roster(a.n),cur=sel.dataset.t==a.n?(+sel.value||0):0;
sel.innerHTML=r?r.map((p,i)=>`<option value=${i}>${PL[p.g]} · ${p.nm}</option>`).join(''):ROL.slice(0,n).map((s,i)=>`<option value=${i}>${s}</option>`).join('');sel.dataset.t=a.n;sel.value=Math.min(cur,sel.options.length-1);
const pk=+sel.value||0,la=r?lineup(a.n,n,pk).nm:squadOf(a.n,n);$('qsq').innerHTML='<b>'+a.n+':</b> '+la.join(', ')+'<br><b>'+b.n+':</b> '+squadOf(b.n,n).join(', ')}
$('pm').addEventListener('input',()=>{pDr=false});$('pm').addEventListener('click',()=>{pDr=false});
/* --- modos de entrenamiento: práctica, atajar y penales --- */
function drillSet(){const m=X.mode;if(!DR||DR.m!=m)DR={m,n:0,max:10};DR.age=0;DR.fired=0;DR.res=0;DR.err=undefined;
if(DR.n>=DR.max){finish();return}
DR.n++;const h=P.find(p=>p.h),o=P.find(p=>p.t==1);P.forEach(p=>{p.vx=p.vy=0;p.px=p.x;p.py=p.y});B.vx=B.vy=0;ph='play';koGo=true;
if(m=='pen'){h.x=HW-HW*.28-42;h.y=0;B.x=HW-HW*.28;B.y=0;o.x=HW-26;o.y=0;DR.msg='Penal '+DR.n+'/'+DR.max+' · pateá al arco'}
else{h.x=-HW+34;h.y=0;const sx=-HW+HW*(.3+Math.random()*.3),sy=(Math.random()*2-1)*HH*.65;o.x=sx;o.y=sy;B.x=sx-26;B.y=sy;DR.msg='Atajá '+DR.n+'/'+DR.max+' · atajadas - goles'}
P.forEach(p=>{p.px=p.x;p.py=p.y});B.px=B.x;B.py=B.y;msg(DR.msg)}
function drillStep(){if(!DR)return;DR.age++;const sp=Math.hypot(B.vx,B.vy);
if(DR.res){if(--DR.res==0)drillSet();return}
if(DR.m=='gk'&&!DR.fired&&DR.age==55){const ty=(Math.random()*2-1)*GH*.85,dx=-HW-B.x,dy=ty-B.y,d=Math.hypot(dx,dy),v=KICK*BIM*(1.3+Math.min(.9,DR.n*.09));B.vx=dx/d*v;B.vy=dy/d*v;DR.fired=1;snd('kick');lastT=1}
if(DR.m=='pen'&&!DR.fired&&sp>1.5){DR.fired=1;DR.age=0;lastT=0}
if(DR.m=='pen'&&!DR.fired&&DR.age>600){DR.fired=1;DR.age=21}
if(DR.fired&&DR.age>20&&(sp<.5||DR.age>260||(DR.m=='gk'&&B.x>-HW*.05))){DR.res=45;if(DR.m=='gk')sc[0]++;else sc[1]++;$('sc').textContent=sc[0]+' - '+sc[1];toast(DR.m=='gk'?'¡Atajaste!':'¡Atajado o afuera!')}}
function drillBot(p){const m=X.mode;if(m=='prac')return p.t==1?{x:0,y:0,kick:false}:null;if(p.t==0)return null;if(m=='gk')return{x:0,y:0,kick:false};
const gx=HW-26;let ty=0;if(DR&&DR.fired&&DR.age>8){if(DR.err===undefined)DR.err=(Math.random()-.5)*GH*(1.3-(X.diff||0)*2);const yy=B.vx>.3?B.y+B.vy*(gx-B.x)/B.vx:B.y;ty=clamp(yy+DR.err,-GH+10,GH-10)}
return{x:clamp((gx-p.x)*.1,-1,1),y:clamp((ty-p.y)*.2,-1,1),kick:false}}
$('gb').onclick=()=>togglePause();$('pr').onclick=e=>{e.stopPropagation();if(paused)togglePause()};
$('prs').onclick=()=>{if(X&&X.mode=='prac'){reset();togglePause()}};
/* --- pulido: ovación, pausa automática, sin menú contextual --- */
function roar(){if(cfg.cel===false)return;try{AC=AC||new(window.AudioContext||window.webkitAudioContext)();if(AC.state=='suspended')AC.resume();const t=AC.currentTime,n=AC.sampleRate*2,b=AC.createBuffer(1,n,AC.sampleRate),d=b.getChannelData(0);for(let i=0;i<n;i++)d[i]=Math.random()*2-1;const s=AC.createBufferSource(),f=AC.createBiquadFilter(),g=AC.createGain();s.buffer=b;f.type='bandpass';f.frequency.setValueAtTime(500,t);f.frequency.linearRampToValueAtTime(1100,t+1.2);f.Q.value=.7;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.35,t+.4);g.gain.exponentialRampToValueAtTime(.0001,t+2.2);s.connect(f);f.connect(g);g.connect(AC.destination);s.start(t);s.stop(t+2.3)}catch(_){}}
