$('gmc').onclick=e=>{const p=e.target.closest('[data-p]');if(p){applyPreset(p.dataset.p);return}const rb=e.target.closest('[data-r]');if(rb){const k=rb.dataset.r;cfg[k]=!cfg[k];if(k=='mx'&&cfg.mx){cfg.aq=false;cfg.rs=Math.max(cfg.rs,1.25)}if(k=='aq'&&cfg.aq)cfg.mx=false;cfg.gq='custom';autoQ=1;saveCfg();resize();renderGm();return}const g=e.target.closest('[data-g]');if(g){const k=g.dataset.g;cfg[k]=!cfg[k];cfg.gq='custom';gfxChanged(0);renderGm();try{syncPm()}catch(_){}return}if(e.target.id=='gx')closeGm()};
