Object.assign(A,{
ccup(){CCD={n:'',f:FMTS[1][0],k:16,groups:4,pool:'mix',col:HX_COLS[0],em:'🏆',sel:[]};CCQ='';scr='cc';render()},
ccset(v){const i=v.indexOf(':'),k=v.slice(0,i),x=v.slice(i+1),d=CCD;if(k=='f')d.f=FMTS[+x][0];else if(k=='k'){d.k=+x;d.sel=d.sel.slice(0,d.k)}else if(k=='g')d.groups=+x;else if(k=='p')d.pool=x;else if(k=='c')d.col=x;else if(k=='e')d.em=x;ccRender()},
cctg(v){const d=CCD,i=d.sel.indexOf(v);if(i>=0)d.sel.splice(i,1);else if(d.sel.length<d.k)d.sel.push(v);else toast('Ya elegiste '+d.k+' equipos');ccList()},
ccsave(){const d=CCD,n=d.n.trim();if(n.length<3){alert('Ponele un nombre a la copa (mínimo 3 letras).');return}if(TOURN.some(t=>t.n.toLowerCase()==n.toLowerCase())){alert('Ya existe una competición con ese nombre.');return}
regCup({t:'Mis copas',n,f:d.f,k:d.k,custom:1,col:d.col,em:d.em,groups:/^Grupos/.test(d.f)?d.groups:0,pool:d.pool,teams:d.sel.slice(0,d.k)});ls('hx_cups',TOURN.filter(t=>t.custom&&!t.mod));pcat='Mis copas';psel=n;pq='';scr='pick';render()},
ccdel(v){if(!confirm('¿Borrar la copa "'+v+'"?'))return;const i=TOURN.findIndex(t=>t.n==v&&t.custom);if(i>=0)TOURN.splice(i,1);ls('hx_cups',TOURN.filter(t=>t.custom&&!t.mod));psel='';if(!TOURN.some(t=>t.t==pcat))pcat='Todos';render()},
mteams(){MTD=mtNew();scr='mt';render()},mtst(v){MTD.st=v;mtRender()},mtpre(v){const p=PRE[+v];MTD.a=p[0];MTD.m=p[1];MTD.d=p[2];MTD.g=p[3];mtRender()},mtnew(){MTD=mtNew();mtRender()},
mted(v){const p=MYA.find(x=>x.n==v);if(p){MTD={edit:1,n:p.n,c1:p.c1,c2:p.c2,st:p.st,a:p.a,m:p.m,d:p.d,g:p.g};mtRender();window.scrollTo(0,0)}},
mtdel(v){if(!confirm('¿Borrar el equipo "'+v+'"?'))return;MYA=MYA.filter(x=>x.n!=v);delete CR[v];window._pa=null;ls('hx_myt',MYA.filter(x=>!x.mod));mtRender()},
mtsave(){const m=MTD,n=m.n.trim();if(n.length<2){alert('Ponele un nombre al club.');return}if(!m.edit&&window.poolAll()[n]){alert('Ya existe un equipo con ese nombre.');return}
regTeam({n,r:ovr(m.a,m.m,m.d,m.g),c:'Mis equipos',l:'',k:'my',a:m.a,m:m.m,d:m.d,g:m.g,c1:m.c1,c2:m.c2,st:m.st});ls('hx_myt',MYA.filter(x=>!x.mod));MTD=mtNew();mtRender();toast('Equipo guardado ✔')}});
/* ===== MODS v2: paquetes de datos (JSON) que cambian casi todo el juego =====
   Un mod puede traer: equipos (escudo, colores, jugadores), copas con reglas propias, estadios con
   colores y medidas, fisica, reglas por defecto, dificultades nuevas y tema visual.
   Es solo datos: no ejecuta codigo. Varios mods activos se combinan (ver modApply). */
const MODKEY='hx_mods';
var MODS=[],MOD_ERR='',MOD_OK='',MOD_TXT='',MOD_DEL='',MB=null,MBID='',MBTAB='datos',MBOPEN={},MODSQ=[],MODINFO={};
const mnr=x=>String(x==null?'':x).trim(),mesc=t=>String(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;'),
 mnorm=x=>mnr(x).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,''),
 mhex=(x,d)=>/^#([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(mnr(x))?mnr(x):d,
 mhex6=(x,d)=>{x=mnr(x);if(/^#[0-9a-f]{3}$/i.test(x))x='#'+x[1]+x[1]+x[2]+x[2]+x[3]+x[3];return /^#[0-9a-f]{6}$/i.test(x)?x.toLowerCase():d},
 mslug=x=>mnorm(x).replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'x',
 mrng=(x,lo,hi,d)=>{if(mnr(x)==='')return d;x=+x;return isFinite(x)?Math.max(lo,Math.min(hi,x)):d},
 mnum=(x,d)=>Math.round(mrng(x,30,99,d)),
 mstyle=x=>{const t=mnorm(x);return/^(liso|plain)/.test(t)?'liso':/^(raya|stripe)/.test(t)?'rayas':/^diag/.test(t)?'diagonal':'franjas'},
 marr=(x,n)=>Array.isArray(x)?x.slice(0,n):[],mobj=x=>!!x&&typeof x=='object'&&!Array.isArray(x),
 mtxt=(x,n)=>Array.from(mnr(x)).slice(0,n).join(''),mclone=x=>JSON.parse(JSON.stringify(x)),mfv=v=>String(Math.round(+v*100)/100);
