function modClean(raw){if(!mobj(raw))throw new Error('El mod tiene que ser un objeto { ... }.');
 const w=[],o={v:2,mod:mtxt(raw.mod||raw.nombre,40),autor:mtxt(raw.autor,30),descripcion:mtxt(raw.descripcion,120),equipos:[],copas:[],estadios:[],fisica:{},reglas:{},dificultades:[],tema:{}};
 if(o.mod.length<2)throw new Error('Falta el nombre del mod ("mod").');
 const off=new Set(NATS.concat(CLUBS).map(x=>x.n));
 marr(raw.equipos,64).forEach((e,i)=>{e=mobj(e)?e:{};const n=mtxt(e.n||e.nombre,28);if(n.length<2){w.push('Equipo #'+(i+1)+' sin nombre: ignorado.');return}
  if(off.has(n)){w.push('"'+n+'" ya existe en el juego: ignorado.');return}if(o.equipos.some(x=>x.n==n)){w.push('"'+n+'" repetido: ignorado.');return}
  const c=marr(e.colores,2),v=mnum(e.nivel,70),pl=mobj(e.jugadores)?e.jugadores:{},gl=(...ks)=>{for(const k of ks)if(Array.isArray(pl[k]))return pl[k].map(x=>mtxt(x,22)).filter(Boolean).slice(0,12);return[]};
  o.equipos.push({n,escudo:mtxt(e.escudo,4),colores:[mhex6(e.c1||c[0],'#e53935'),mhex6(e.c2||c[1],'#ffffff')],estilo:mstyle(e.estilo),nivel:v,
   ataque:mnum(e.ataque,v),medio:mnum(e.medio,v),defensa:mnum(e.defensa,v),arquero:mnum(e.arquero,v),
   jugadores:{arquero:gl('arquero','arqueros','G'),defensas:gl('defensas','D'),medios:gl('medios','M'),delanteros:gl('delanteros','F','A')}})});
 const known=new Set([...off,...o.equipos.map(x=>x.n),...MYA.filter(x=>!x.mod).map(x=>x.n),...MODS.flatMap(m=>m.data.equipos.map(x=>x.n))]);
 /* estadios */
 marr(raw.estadios,12).forEach((s,i)=>{s=mobj(s)?s:{};const n=mtxt(s.n||s.nombre,28);if(n.length<2){w.push('Estadio #'+(i+1)+' sin nombre: ignorado.');return}
  if(o.estadios.some(x=>x.n.toLowerCase()==n.toLowerCase())||/^(classic|bazinga)$/i.test(n)){w.push('Estadio "'+n+'" repetido: ignorado.');return}
  const base=/fut/.test(mnorm(s.base))?'futsal':'clasica',D=MSTD[base],alto=Math.round(mrng(s.alto,120,360,D.alto)),col={},cs=mobj(s.colores)?s.colores:{};
  MSKIN.forEach(k=>{const v=mhex6(cs[k[0]],'');if(v)col[k[0]]=v});
  o.estadios.push({n,base,ancho:Math.round(mrng(s.ancho,250,800,D.ancho)),alto,arco:Math.round(Math.min(mrng(s.arco,36,130,D.arco),alto*.62)),red:Math.round(mrng(s.red,20,60,D.red)),colores:col})});
 const estOk=v=>{v=mnr(v);return v&&(/^(classic|bazinga)$/i.test(v)||o.estadios.some(x=>x.n==v))?(/^classic$/i.test(v)?'classic':/^bazinga$/i.test(v)?'bazinga':v):''};
 const difs=[];marr(raw.dificultades,8).forEach((d,i)=>{d=mobj(d)?d:{};const n=mtxt(d.n||d.nombre,16),v=mrng(d.valor,-.6,2,null);if(n.length<2||v==null){w.push('Dificultad #'+(i+1)+' incompleta: ignorada.');return}
  if(MDIF0.some(x=>x[1].toLowerCase()==n.toLowerCase())||difs.some(x=>x.n.toLowerCase()==n.toLowerCase())){w.push('Dificultad "'+n+'" repetida: ignorada.');return}difs.push({n,valor:Math.round(v*100)/100})});o.dificultades=difs;
 const rg=(r)=>{r=mobj(r)?r:{};const q={};if(mnr(r.jugadores)!=='')q.jugadores=Math.round(mrng(r.jugadores,1,3,2));if(mnr(r.duracion)!=='')q.duracion=Math.round(mrng(r.duracion,.5,10,2)*2)/2;
  if(mnr(r.limiteGoles)!=='')q.limiteGoles=Math.round(mrng(r.limiteGoles,0,30,0));if(mnr(r.dificultad)!=='')q.dificultad=mrng(r.dificultad,-.6,2,0);const e=estOk(r.estadio);if(e)q.estadio=e;
  if(r.vuelta!=null&&r.vuelta!=='')q.vuelta=r.vuelta===true||r.vuelta===1||r.vuelta==='1'||r.vuelta==='true';return q};
 o.reglas=rg(raw.reglas);
 /* fisica */
 const fi=mobj(raw.fisica)?raw.fisica:{};F_FIS.forEach(f=>{if(mnr(fi[f[0]])!==''){const v=mrng(fi[f[0]],f[2],f[3],1);if(Math.abs(v-1)>1e-9)o.fisica[f[0]]=Math.round(v*100)/100}});
 /* tema */
 const th=mobj(raw.tema)?raw.tema:{};MTHEME.forEach(k=>{const v=mhex6(th[k[0]],'');if(v)o.tema[k[0]]=v});if(mtxt(th.titulo,24))o.tema.titulo=mtxt(th.titulo,24);if(mtxt(th.lema,40))o.tema.lema=mtxt(th.lema,40);
 /* copas */
 marr(raw.copas,20).forEach((c,i)=>{c=mobj(c)?c:{};const n=mtxt(c.n||c.nombre,28);if(n.length<3){w.push('Copa #'+(i+1)+' sin nombre (mínimo 3 letras): ignorada.');return}
  if(TOURN.some(t=>t.n.toLowerCase()==n.toLowerCase()&&!t.mod)||o.copas.some(x=>x.n.toLowerCase()==n.toLowerCase())){w.push('Ya existe una competición llamada "'+n+'": ignorada.');return}
  const pl=({club:'club',clubes:'club',nat:'nat',selecciones:'nat',mod:'mod',solo:'mod'})[mnorm(c.pool||c.equiposDe)]||'mix',tm=[];
  marr(c.equipos,60).forEach(x=>{x=mnr(x);if(!known.has(x))w.push('"'+n+'": no existe el equipo "'+x+'" (se completa con otros).');else if(tm.indexOf(x)<0)tm.push(x)});
  let k=Math.max(4,Math.min(48,Math.round(+(c.cantidad||c.k))||8)),fi=MFMT.findIndex(f=>f[0]==c.formato);if(fi<0){const t=mnorm(c.formato);fi=/grupo/.test(t)?1:/liga/.test(t)?(/ko|elimin|copa/.test(t)?3:0):2}
  let pool=pl,gr=0;if(pl=='mod'){const nm=o.equipos.length;if(nm<4){w.push('"'+n+'": "solo equipos del mod" necesita 4 o más equipos: pasa a Mixto.');pool='mix'}else k=Math.min(k,nm)}
  if(fi==1){const go=groupOpts(k,true);if(!go.length){fi=3;w.push('"'+n+'": no se pueden armar grupos con '+k+' equipos, pasa a Liga + KO.')}else gr=go.indexOf(+c.grupos)>-1?+c.grupos:defGroups(k,true)}
  o.copas.push({n,formato:MFMT[fi][0],cantidad:k,grupos:gr,pool,color:mhex6(c.color,'#ff7a1a'),emblema:mtxt(c.emblema,4)||'🏆',equipos:tm,reglas:rg(c.reglas)})});
 return{o,w}}
/* ---- aplicar: varios mods activos se combinan (fisica se multiplica; reglas/tema: gana el ultimo) ---- */
var MODPHYS={},MODRULES={},MODDIFF=[],MODTHEME={},MODEM={},MODSTD=[];
function modKey(name){const v=mnr(name);if(/^classic$/i.test(v))return'classic';if(/^bazinga$/i.test(v))return'bazinga';const s=MODSTD.find(x=>x.n==v);return s?s.key:null}
function modMix(h,k){h=mhex6(h,'#000000');const n=i=>Math.max(0,Math.min(255,Math.round(parseInt(h.substr(1+i*2,2),16)*(1-k))));return'#'+[0,1,2].map(i=>('0'+n(i).toString(16)).slice(-2)).join('')}
function modApply(){MYA=MYA.filter(x=>!x.mod);for(let i=TOURN.length-1;i>=0;i--)if(TOURN[i].mod)TOURN.splice(i,1);
 Object.keys(MAPS).forEach(k=>{if(/^m_/.test(k))delete MAPS[k]});MODSQ.forEach(n=>delete SQP[n]);MODSQ=[];MODEM={};MODPHYS={};MODRULES={};MODDIFF=[];MODTHEME={};MODSTD=[];
 MODS.forEach(m=>{if(!m.on)return;const d=m.data;
  d.equipos.forEach(e=>{if(MYA.some(x=>x.n==e.n&&!x.mod))return;regTeam({n:e.n,r:ovr(e.ataque,e.medio,e.defensa,e.arquero),c:'Mod: '+d.mod,l:'',k:'my',a:e.ataque,m:e.medio,d:e.defensa,g:e.arquero,c1:e.colores[0],c2:e.colores[1],st:MODST[e.estilo]||'band',mod:m.id});
   if(e.escudo)MODEM[e.n]=e.escudo;const j=e.jugadores;if(j&&(j.arquero.length+j.defensas.length+j.medios.length+j.delanteros.length)){SQP[e.n]={G:j.arquero.slice(),D:j.defensas.slice(),M:j.medios.slice(),F:j.delanteros.slice()};MODSQ.push(e.n)}});
  d.estadios.forEach(s=>{const key='m_'+mslug(s.n),b=MAPS[MSTD[s.base].key],pbx=Math.max(s.ancho+(b.PBX-b.HW),s.ancho+s.red+10),pby=s.alto+(b.PBY-b.HH),sk={},cm={fondo:'out',cesped:'cs',rayas:'rs',lineas:'lc',palos:'post',pelota:'ball',red:'net'};
   Object.keys(s.colores).forEach(k=>{sk[cm[k]]=s.colores[k]});
   MAPS[key]=Object.assign({},b,{n:s.n,HW:s.ancho,HH:s.alto,GH:s.arco,GD:s.red,PBX:pbx,PBY:pby,CX:pbx+15,CY:pby+15,SP:Math.round(s.ancho*b.SP/b.HW),sk,mod:1,sc:[s.ancho/b.HW,s.alto/b.HH]});MODSTD.push({n:s.n,key})});
  d.copas.forEach(c=>{if(TOURN.some(t=>t.n==c.n&&!t.mod))return;regCup({t:'Mods',n:c.n,f:FMTS[Math.max(0,MFMT.findIndex(f=>f[0]==c.formato))][0],k:c.cantidad,custom:1,mod:m.id,col:c.color,em:c.emblema,groups:c.grupos,pool:c.pool,teams:c.equipos.slice(0,c.cantidad),rules:c.reglas})});
  Object.keys(d.fisica).forEach(k=>{MODPHYS[k]=(MODPHYS[k]==null?1:MODPHYS[k])*d.fisica[k]});
  Object.assign(MODRULES,d.reglas);d.dificultades.forEach(x=>{if(!MODDIFF.some(y=>y[1]==x.n))MODDIFF.push([x.valor,x.n])});Object.assign(MODTHEME,d.tema)});
 F_FIS.forEach(f=>{if(MODPHYS[f[0]]!=null)MODPHYS[f[0]]=Math.max(f[2],Math.min(f[3],MODPHYS[f[0]]))});
 window._pa=null;modThemeApply()}
function modThemeApply(){const r=document.documentElement.style,t=MODTHEME||{};['--bg','--p','--p2','--t'].forEach(k=>r.removeProperty(k));
 if(t.fondo)r.setProperty('--bg',t.fondo);if(t.panel){r.setProperty('--p',t.panel);r.setProperty('--p2',modMix(t.panel,-.25))}if(t.texto)r.setProperty('--t',t.texto);
 try{applyTheme(window.__thn||'')}catch(e){}}
/* ---- ganchos del motor ---- */
function modPhys(M){const P=MODPHYS||{},f=k=>P[k]==null?1:P[k],cl=(x,a,b)=>Math.max(a,Math.min(b,x));
 M.PR=15*f('tamanoJugador');M.PIM=.5/f('pesoJugador');M.KICKP=5*f('potenciaPatada');M.BR=M.BR*f('tamanoPelota');M.BIM=M.BIM/f('pesoPelota');
 M.PD=f('friccionJugador')==1?.96:cl(1-.04*f('friccionJugador'),.5,1);M.BD=f('friccionPelota')==1?.99:cl(1-.01*f('friccionPelota'),.5,1);
 M.ACC=M.ACC*f('velocidadJugador');M.KACC=M.KACC*f('velocidadJugador');M.GS=f('velocidadJuego');
 const rb=f('rebote');if(rb!=1)['WE','EE','PE_','NE'].forEach(k=>{if(M[k])M[k]=Math.min(1.2,M[k]*rb)});
 M.GH=Math.min(M.GH*f('tamanoArco'),M.HH*.62);M.PS=M.PS*f('tamanoPalos');return M}
function modMapOpts(){return[['bazinga','Futsal x3 Bazinga'],['classic','Classic']].concat(MODSTD.map(s=>[s.key,s.n]))}
function modDiffOpts(){return MDIF0.concat(MODDIFF).sort((a,b)=>a[0]-b[0])}
function modRules(){const o={};if(MODRULES.jugadores)o.fmt=MODRULES.jugadores;if(MODRULES.duracion)o.dur=MODRULES.duracion;if(MODRULES.limiteGoles!=null)o.lim=MODRULES.limiteGoles;if(MODRULES.dificultad!=null)o.diff=MODRULES.dificultad;
 const k=MODRULES.estadio&&modKey(MODRULES.estadio);if(k)o.map=k;if(MODRULES.vuelta!=null)o.vuelta=MODRULES.vuelta?1:0;return o}
function cupRules(n){const c=COMP(n||''),r=c&&c.rules;if(!r)return{};const o={};if(r.jugadores)o.fmt=r.jugadores;if(r.duracion)o.dur=r.duracion;if(r.limiteGoles!=null)o.lim=r.limiteGoles;if(r.dificultad!=null)o.diff=r.dificultad;
 const k=r.estadio&&modKey(r.estadio);if(k)o.map=k;if(r.vuelta!=null)o.vuelta=r.vuelta?1:0;return o}
function modTheme(t,n){const m=MODTHEME||{};if(!m.acento)return t;t=Object.assign({},t);const c=COMP(n||'');if(c&&c.custom&&!c.mod)return t;t.a=m.acento;t.d=modMix(m.acento,.45);t.b1=modMix(m.acento,.78);t.b2=modMix(m.acento,.93);return t}
function modTitle(){return mesc((MODTHEME&&MODTHEME.titulo)||'HaxCup')}
function modLema(){return MODTHEME&&MODTHEME.lema?`<p class=m style="text-align:center;margin:0 0 8px">${mesc(MODTHEME.lema)}</p>`:''}
function modCrest(n,s){const c=CR[n]||['#444','plain','#999'];return`<span class=cr style="width:${s}px;height:${s}px;border-radius:50%;background:linear-gradient(135deg,${c[0]} 50%,${c[2]} 50%);display:inline-flex;align-items:center;justify-content:center;font-size:${Math.round(s*.5)}px;line-height:1;overflow:hidden;box-shadow:0 0 0 2px #ffffff33">${mesc(MODEM[n])}</span>`}
/* ---- instalar / prompt ---- */
function modAdd(o,oldId){const id=mslug(o.mod);if(oldId&&oldId!=id&&MODS.some(x=>x.id==id))throw new Error('Ya hay otro mod con ese nombre.');
 let i=MODS.findIndex(x=>x.id==(oldId||id));if(i<0)i=MODS.findIndex(x=>x.id==id);const m={id,on:i>=0?MODS[i].on:true,data:o};if(i<0)MODS.push(m);else MODS[i]=m;ls(MODKEY,MODS);modApply();return m}
function modInstall(txt){let raw;try{raw=JSON.parse(txt)}catch(e){throw new Error('JSON inválido: '+e.message)}
 const r=modClean(raw);if(!r.o.equipos.length&&!r.o.copas.length&&!r.o.estadios.length&&!Object.keys(r.o.fisica).length&&!Object.keys(r.o.reglas).length&&!r.o.dificultades.length&&!Object.keys(r.o.tema).length)throw new Error('El mod no cambia nada: agregale equipos, copas, estadios, física, reglas, dificultades o tema.'+(r.w.length?' '+r.w.join(' '):''));
 const m=modAdd(r.o);r.id=m.id;return r}
function modPrompt(){return'Quiero que me escribas un mod para mi juego de fútbol. Respondé SOLO con un JSON válido (sin explicaciones ni ```), con esta forma (todo es opcional salvo "mod"; podés usar solo las partes que quieras):\n'+JSON.stringify(MEX,null,1)+
 '\n\nReglas:\n- "mod": nombre (obligatorio).\n- "equipos": n=nombre (no puede repetir clubes reales), escudo=emoji o 1-3 letras, colores=[#hex,#hex], estilo=liso|franjas|rayas|diagonal, nivel=30 a 99 (o ataque/medio/defensa/arquero por separado), jugadores={arquero,defensas,medios,delanteros} con listas de nombres (opcional).\n'+
 '- "copas": n (mín. 3 letras), formato=Liga|Grupos + KO|Eliminatoria|Liga + KO, cantidad=4 a 48, color=#hex, emblema=emoji, equipos=lista de nombres, pool=mix|clubes|selecciones|mod, reglas={jugadores 1-3, duracion en minutos (0.5 a 10), limiteGoles 0-30, dificultad -0.6 a 2, estadio=nombre, vuelta=true|false} (opcional).\n'+
 '- "estadios": n, base=clasica|futsal, ancho 250-800, alto 120-360, arco 36-130, red 20-60, colores={fondo,cesped,rayas,lineas,palos,pelota,red}.\n'+
 '- "fisica": multiplicadores (1 = normal): '+F_FIS.map(f=>f[0]+' '+f[2]+'-'+f[3]).join(', ')+'.\n'+
 '- "reglas": valores por defecto del partido (jugadores, duracion, limiteGoles, dificultad, estadio).\n- "dificultades": [{n, valor}] valor de -0.6 a 2 (0 = Normal, 0.5 = Leyenda).\n- "tema": acento, fondo, panel, texto (#hex), titulo, lema.\n\nQuiero: '}
/* ---- constructor visual: un formulario por pestaña, todo escribe en MB ---- */
const MBTABS=[['datos','📝 Datos'],['equipos','👕 Equipos'],['copas','🏆 Copas'],['estadios','🏟 Estadios'],['fisica','⚙ Física'],['reglas','📏 Reglas'],['tema','🎨 Tema'],['codigo','{ } Código']];
const mbget=(p)=>p.split('.').reduce((o,k)=>o==null?o:o[k],MB);
function mbset(p,v){const a=p.split('.'),l=a.pop();let o=MB;a.forEach(k=>{if(o[k]==null)o[k]=/^\d+$/.test(k)?[]:{};o=o[k]});o[l]=v}
const mbopt=(a,cur)=>a.map(o=>`<option value="${mesc(o[0])}"${String(cur)==String(o[0])?' selected':''}>${mesc(o[1])}</option>`).join('');
function mfT(p,l,ph,ml){return`<label class=fld><span>${l}</span><input type=text data-p="${p}" data-t=t value="${mesc(mbget(p)||'')}" placeholder="${mesc(ph||'')}" maxlength=${ml||40}></label>`}
function mfN(p,l,min,max,st,d,unit){let v=mbget(p);const has=v!=null&&v!=='';if(!has)v=d;return`<label class=fld><span>${l}<b class=mbv>${mfv(v)}${unit||''}</b></span><input type=range data-p="${p}" data-t=n data-u="${unit||''}" min=${min} max=${max} step=${st} value="${v}"></label>`}
function mfC(p,l,d){const v=mhex6(mbget(p),d);return`<label class=fld style="flex:1;min-width:110px"><span>${l}</span><input type=color data-p="${p}" data-t=c value="${v}"></label>`}
function mfS(p,l,opts,d){const v=mbget(p);return`<label class=fld><span>${l}</span><select data-p="${p}" data-t=s>${mbopt(opts,v==null||v===''?d:v)}</select></label>`}
function mfCsv(p,l,ph){const v=mbget(p);return`<label class=fld><span>${l}</span><input type=text data-p="${p}" data-t=csv value="${mesc(Array.isArray(v)?v.join(', '):'')}" placeholder="${mesc(ph||'')}"></label>`}
function mfB(p,l){const v=mbget(p);return`<label class=fld style="flex-direction:row;align-items:center;gap:8px"><input type=checkbox data-p="${p}" data-t=b${v?' checked':''}><span>${l}</span></label>`}
const mbCard=(k,title,body,del)=>`<details class=card data-k="${k}"${MBOPEN[k]?' open':''}><summary><b>${title}</b></summary><div class=col style="gap:10px;margin-top:10px">${body}${del?`<button data-a=mbdel data-v="${del}">🗑 Quitar</button>`:''}</div></details>`;
function mbStdOpts(){return[['','(el normal)'],['bazinga','Futsal x3 Bazinga'],['classic','Classic']].concat((MB.estadios||[]).filter(s=>mnr(s.n).length>1).map(s=>[s.n,s.n+' (de este mod)']))}
function mbDiffOpts(){const d=MDIF0.concat((MB.dificultades||[]).filter(x=>mnr(x.n)&&x.valor!=null).map(x=>[+x.valor,x.n])).sort((a,b)=>a[0]-b[0]);return[['','(la normal)']].concat(d.map(x=>[String(x[0]),x[1]]))}
function mbPrev(s,i){const D=MSTD[s.base]||MSTD.clasica,c=k=>mhex6((s.colores||{})[k],MSKIN.find(x=>x[0]==k)[2]),W=(s.ancho||D.ancho),H=(s.alto||D.alto),g=s.arco||D.arco,r=s.red||D.red,sc=300/(W+r+40);
 return`<svg id="mbprev${i}" viewBox="${-(W+r+20)} ${-(H+20)} ${(W+r+20)*2} ${(H+20)*2}" style="width:100%;border-radius:10px;background:${c('fondo')}"><rect x=${-W} y=${-H} width=${W*2} height=${H*2} fill="${c('cesped')}" /><g stroke="${c('rayas')}" stroke-width=${W/9}>${[-3,-1,1,3].map(k=>`<line x1=${k*W/4} y1=${-H} x2=${k*W/4} y2=${H} />`).join('')}</g><g fill=none stroke="${c('lineas')}" stroke-width=${Math.max(3,W/90)}><rect x=${-W} y=${-H} width=${W*2} height=${H*2} /><line x1=0 y1=${-H} x2=0 y2=${H} /><circle r=${Math.round(H*.32)} /></g><g fill=none stroke="${c('red')}" stroke-width=${Math.max(3,W/90)}><rect x=${-W-r} y=${-g} width=${r} height=${g*2} /><rect x=${W} y=${-g} width=${r} height=${g*2} /></g><g fill="${c('palos')}"><circle cx=${-W} cy=${-g} r=${Math.max(5,W/45)} /><circle cx=${-W} cy=${g} r=${Math.max(5,W/45)} /><circle cx=${W} cy=${-g} r=${Math.max(5,W/45)} /><circle cx=${W} cy=${g} r=${Math.max(5,W/45)} /></g><circle r=${Math.max(7,W/38)} fill="${c('pelota')}" stroke="#000" stroke-width=3 /></svg>`}
