 if(ty=='n'){v=+v;const mm=/^equipos\.(\d+)\.nivel$/.exec(t.dataset.p);if(mm){const e=MB.equipos[+mm[1]],old=e.nivel==null?70:e.nivel;['ataque','medio','defensa','arquero'].forEach(k=>{if(e[k]==null||e[k]==old){e[k]=v;const q=ui.querySelector('[data-p="equipos.'+mm[1]+'.'+k+'"]');if(q){q.value=v;const z=q.parentNode.querySelector('.mbv');if(z)z.textContent=mfv(v)}}})}const s=t.parentNode.querySelector('.mbv');if(s)s.textContent=mfv(v)+(t.dataset.u||'')}else if(ty=='csv')v=v.split(',').map(x=>x.trim()).filter(Boolean);else if(ty=='b')v=t.checked;else if(ty=='s'&&t.dataset.p.indexOf('dificultad')>-1&&/reglas\.dificultad$/.test(t.dataset.p))v=v===''?undefined:+v;
 if(v===undefined||(ty=='s'&&v==='')){const a=t.dataset.p.split('.'),l=a.pop(),o=a.reduce((x,k)=>x&&x[k],MB);if(o)delete o[l]}else mbset(t.dataset.p,v);
