 mbdel(v){const[k,i]=v.split(':');if(MB[k]){MB[k].splice(+i,1);MBOPEN={};mbRender()}},
 mbpre(v){const[i,p]=v.split(':'),e=MB.equipos[+i],b=MPRESET[p]||[0,0,0,0],n=e.nivel==null?70:e.nivel;['ataque','medio','defensa','arquero'].forEach((k,j)=>{e[k]=Math.max(30,Math.min(99,Math.round(n+b[j])))});MBOPEN['eqa'+i]=true;MBOPEN['eq'+i]=true;mbRender()},
