const AMB=$('amb'),ax=AMB.getContext('2d'),RM=matchMedia('(prefers-reduced-motion:reduce)').matches;let aTh=th(''),aW=0,aH=0,aP=[],aLast=0;
function ambInit(){aW=AMB.width=Math.ceil(innerWidth/2);aH=AMB.height=Math.ceil(innerHeight/2);aP=Array.from({length:42},()=>({x:rnd()*aW,y:rnd()*aH,r:1+rnd()*3,v:.15+rnd()*.5,p:rnd()*6.28}));ambDraw(performance.now(),1)}
function ambSet(n){aTh=th(n||'');aStyle(aTh.st);if(aW)ambDraw(performance.now(),1)}
function ambDraw(t,once){if(!once&&(document.hidden||!E_game.hidden||t-aLast<33)){return}aLast=t;const W=aW,H=aH,p=aTh.pat,tt=t/1000;
let g=ax.createLinearGradient(0,0,0,H);g.addColorStop(0,aTh.b1);g.addColorStop(1,aTh.b2);ax.globalCompositeOperation='source-over';ax.globalAlpha=1;ax.fillStyle=g;ax.fillRect(0,0,W,H);
ax.globalCompositeOperation='lighter';
for(let i=0;i<3;i++){const x=W*(.17+i*.33)+Math.sin(tt*.5+i*2)*W*.05,w=W*.2+Math.sin(tt*.4+i)*W*.04;g=ax.createLinearGradient(x,0,x,H*.85);g.addColorStop(0,aTh.a);g.addColorStop(1,'#000');ax.globalAlpha=.13;ax.fillStyle=g;ax.beginPath();ax.moveTo(x-3,0);ax.lineTo(x+3,0);ax.lineTo(x+w,H*.85);ax.lineTo(x-w,H*.85);ax.fill()}
ax.strokeStyle=aTh.a;ax.lineWidth=2;ax.globalAlpha=.07;ax.beginPath();ax.arc(W/2,H*1.02,H*.38,0,7);ax.stroke();ax.beginPath();ax.moveTo(0,H*1.02);ax.lineTo(W,H*1.02);ax.stroke();
ax.fillStyle=aTh.a;ax.strokeStyle=aTh.a;
aP.forEach((q,i)=>{if(p=='stars'){const a=.25+.6*Math.abs(Math.sin(tt*q.v*2+q.p));ax.globalAlpha=a*.7;const s=q.r*1.6;ax.fillRect(q.x-s/2,q.y-.5,s,1);ax.fillRect(q.x-.5,q.y-s/2,1,s)}
else if(p=='dots'){q.y-=q.v*.5;if(q.y<-6)q.y=H+6;ax.globalAlpha=.16+.1*Math.sin(tt+q.p);ax.beginPath();ax.arc(q.x+Math.sin(tt*.4+q.p)*6,q.y,q.r*2,0,7);ax.fill()}
else if(p=='rings'){if(i<8){const k=((tt*.12+i/8)%1);ax.globalAlpha=.12*(1-k);ax.lineWidth=1.5;ax.beginPath();ax.arc(W*((i*37%100)/100),H*((i*53%100)/100),k*H*.35,0,7);ax.stroke()}}
else if(p=='diag'){if(i<10){const x=((i/10+tt*.02)%1)*(W+H)-H;ax.globalAlpha=.05;ax.lineWidth=14;ax.beginPath();ax.moveTo(x,0);ax.lineTo(x+H,H);ax.stroke()}}
else{if(i<10){const x=((i/10+tt*.015)%1)*W;ax.globalAlpha=.05;ax.fillRect(x,0,W*.04,H)}}});
ax.globalAlpha=1;ax.globalCompositeOperation='source-over'}
function ambLoop(t){ambDraw(t);requestAnimationFrame(ambLoop)}
addEventListener('resize',ambInit);ambInit();if(!RM)requestAnimationFrame(ambLoop);
