const AMU=$('amu');let AX=null,aG=null,aBP=null,aOn=cfg.amb!==false,swell=0,swT=0;
function aStyle(s){if(aBP)aBP.frequency.value=s=='sud'?950:s=='nat'?720:s=='eu'?620:780}
function sndStart(){if(!aOn)return;try{if(!AX){AX=new(window.AudioContext||window.webkitAudioContext)();const len=AX.sampleRate*3,buf=AX.createBuffer(1,len,AX.sampleRate),d=buf.getChannelData(0);let b0=0,b1=0,b2=0;for(let i=0;i<len;i++){const w=Math.random()*2-1;b0=.99765*b0+w*.099;b1=.963*b1+w*.2965;b2=.57*b2+w*1.05;d[i]=(b0+b1+b2+w*.1848)*.11}
const s=AX.createBufferSource();s.buffer=buf;s.loop=true;aBP=AX.createBiquadFilter();aBP.type='bandpass';aBP.Q.value=.45;const lp=AX.createBiquadFilter();lp.type='lowpass';lp.frequency.value=2000;aG=AX.createGain();aG.gain.value=0;s.connect(aBP);aBP.connect(lp);lp.connect(aG);aG.connect(AX.destination);s.start();aStyle(aTh.st)}if(AX.state=='suspended')AX.resume()}catch(e){AX=null}}
function ambVol(){AMU.hidden=!E_game.hidden;AMU.textContent=aOn?'🔊':'🔇';if(!AX||!aG)return;const now=Date.now();if(now>swT){swell=swell?0:.07;swT=now+(swell?1800:7000+rnd()*8000)}
const v=aOn&&E_game.hidden&&!document.hidden?.09+Math.sin(now/3500)*.025+swell:0;aG.gain.setTargetAtTime(Math.max(0,v),AX.currentTime,.5)}
setInterval(ambVol,300);addEventListener('pointerdown',sndStart);
AMU.onclick=e=>{e.stopPropagation();aOn=!aOn;cfg.amb=aOn;saveCfg();if(aOn)sndStart();ambVol()};ambVol();

